"""Drift statistics built from NumPy and SciPy, so you can see exactly what each one measures."""
import numpy as np
from scipy import stats
from scipy.spatial.distance import jensenshannon

EPS = 1e-4          # stands in for an empty bin, so log(0) never happens


def _clean(values):
    values = np.asarray(values, dtype=float)
    return values[~np.isnan(values)]


def bin_edges(reference, bins=10):
    """Inner edges at the reference's quantiles: each bin holds about 1/bins of the reference."""
    qs = np.quantile(_clean(reference), np.linspace(0, 1, bins + 1)[1:-1])
    return np.unique(qs)


def shares(values, edges):
    """Share of values in each bin; the outer bins are open-ended, so nothing falls outside."""
    idx = np.searchsorted(edges, _clean(values), side="right")
    counts = np.bincount(idx, minlength=len(edges) + 1)
    return counts / counts.sum()


def psi(reference, current, bins=10):
    """Population stability index: sum of (actual - expected) * ln(actual / expected) over bins."""
    edges = bin_edges(reference, bins)
    e = np.clip(shares(reference, edges), EPS, None)
    a = np.clip(shares(current, edges), EPS, None)
    return float(np.sum((a - e) * np.log(a / e)))


def category_shares(values, categories):
    values = list(values)
    return np.array([values.count(c) for c in categories]) / len(values)


def psi_categorical(reference, current):
    categories = sorted(set(reference) | set(current))      # a new category is a bin of its own
    e = np.clip(category_shares(reference, categories), EPS, None)
    a = np.clip(category_shares(current, categories), EPS, None)
    return float(np.sum((a - e) * np.log(a / e)))


def ks(reference, current):
    """Two-sample Kolmogorov-Smirnov: D is the largest gap between the two empirical CDFs."""
    result = stats.ks_2samp(_clean(reference), _clean(current))
    return float(result.statistic), float(result.pvalue)


def chi2(reference, current):
    """Chi-squared test of the category counts, with Cramer's V as the effect size (0 to 1)."""
    categories = sorted(set(reference) | set(current))
    ref, cur = list(reference), list(current)
    table = np.array([[ref.count(c) for c in categories], [cur.count(c) for c in categories]])
    statistic, p_value, dof, _ = stats.chi2_contingency(table)
    v = np.sqrt(statistic / (table.sum() * (min(table.shape) - 1)))
    return float(statistic), float(p_value), float(v)


def js_distance(reference, current, bins=10):
    """Jensen-Shannon distance with base 2: 0 for identical distributions, 1 at most."""
    edges = bin_edges(reference, bins)
    return float(jensenshannon(shares(reference, edges), shares(current, edges), base=2))

